    kn: "ಈ ದೃಷ್ಟಿ ಬದಲಾವಣೆಗಳಲ್ಲಿ ಯಾವುದನ್ನಾದರೂ ನೀವು ಅನುಭವಿಸಿದರೆ, ವಾರ್ಷಿಕ ತಪಾಸಣೆಗಾಗಿ ಕಾಯಬೇಡಿ - ತಕ್ಷಣವೇ ಕಣ್ಣಿನ ವೈದ್ಯರನ್ನು ಅಥವಾ ಆಸ್ಪತ್ರೆಯನ್ನು ಸಂಪರ್ಕಿಸಿ:",
