    te: "మీరు ఈ దృష్టి మార్పులలో దేనినైనా అనుభవిస్తే, వార్షిక స్క్రీనింగ్ కోసం వేచి ఉండకండి-వెంటనే కంటి వైద్యుడిని లేదా ఆసుపత్రిని సంప్రదించండి:",
    ml: "ഈ കാഴ്ച വ്യതിയാനങ്ങളിൽ എന്തെങ്കിലും അനുഭവപ്പെടുകയാണെങ്കിൽ, വാർഷിക പരിശോധനയ്ക്കായി കാത്തിരിക്കരുത്-ഉടൻ തന്നെ ഒരു നേത്രരോഗവിദഗ്ദ്ധനെയോ ആശുപത്രിയെയോ സമീപിക്കുക:",
