  "pregnancySchedule": {
    hi: "गर्भधारण से पहले या पहली तिमाही में जांच; प्रत्येक तिमाही में दोहराएं।",
    kn: "ಗರ್ಭಧಾರಣೆಯ ಮೊದಲು ಅಥವಾ ಮೊದಲ ತ್ರೈಮಾಸಿಕದಲ್ಲಿ ತಪಾಸಣೆ; ಪ್ರತಿ ತ್ರೈಮಾಸಿಕದಲ್ಲೂ ಪುನರಾವರ್ತಿಸಿ.",
    ta: "கருத்தரிப்பதற்கு முன் அல்லது முதல் மூன்று மாதங்களில் பரிசோதனை; ஒவ்வொரு மூன்று மாதங்களுக்கும் பரிசோதிக்கவும்.",
    te: "గర్భధారణకు ముందు లేదా మొదటి త్రైమాసికంలో స్క్రీనింగ్; ప్రతి త్రైమాసికంలో పునరావృతం చేయండి.",
    ml: "ഗർഭധാരണത്തിന് മുമ്പോ ആദ്യ ത്രിമാസത്തിലോ പരിശോധന; തുടർന്ന് ഓരോ ത്രിമാസത്തിലും ആവർത്തിക്കുക.",
  },
