  "ctaEvaluationSubtitle": {
    hi: "मल्टीमॉडल एआई के साथ रेटिना तस्वीरों का मूल्यांकन करें या पूर्व-लोड किए गए नैदानिक मामलों का अन्वेषण करें।",
    kn: "ವಿವರಣಾತ್ಮಕ ಮಲ್ಟಿಮೋಡಲ್ ಎಐ ಮೂಲಕ ರೆಟಿನಾ ಫೋಟೋಗಳನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ ಅಥವಾ ಕ್ಲಿನಿಕಲ್ ಕೇಸ್‌ಗಳನ್ನು ಅನ್ವೇಷಿಸಿ.",
    ta: "விளக்கமளிக்கக்கூடிய ஏஐ மூலம் விழித்திரை புகைப்படங்களை மதிப்பாய்வு செய்யவும் அல்லது மாதிரி நிகழ்வுகளை ஆராயவும்.",
    te: "వివరణాత్మక మల్టీమోడల్ AI తో రెటీనా ఫోటోలను విశ్లేషించండి లేదా క్లినికల్ కేసులను అన్వేషించండి.",
    ml: "മൾട്ടിമോഡൽ എഐ ഉപയോഗിച്ച് റെറ്റിന ഫോട്ടോകൾ വിലയിരുത്തുക അല്ലെങ്കിൽ ക്ലിനിക്കൽ കേസുകൾ പരിശോധിക്കുക.",
  },
