  "All predictions, Grad-CAM overlays, and biomarker detections require confirmatory examination by a licensed ophthalmologist.": {
    hi: "सभी भविष्यवाणियों, ग्रैड-सीएएम और बायोमार्कर का लाइसेंस प्राप्त नेत्र रोग विशेषज्ञ द्वारा पुष्टिकरण आवश्यक है।",
    kn: "ಎಲ್ಲಾ ಅಂದಾಜುಗಳು, ಗ್ರಾಡ್-ಕ್ಯಾಮ್ ಓವರ್‌ಲೇಗಳು ಮತ್ತು ಬಯೋಮಾರ್ಕರ್ ಪತ್ತೆಗಳಿಗೆ ಪರವಾನಗಿ ಪಡೆದ ನೇತ್ರ ತಜ್ಞರ ದೃಢೀಕರಣ ಪರೀಕ್ಷೆ ಅಗತ್ಯವಿದೆ.",
    ta: "அனைத்து கணிப்புகள் மற்றும் பகுப்பாய்வுகளுக்கு உரிமம் பெற்ற கண் மருத்துவரின் உறுதிப்படுத்தல் தேவை.",
    te: "అన్ని అంచనాలు మరియు బయోమార్కర్ గుర్తింపులకు అర్హత కలిగిన నేత్ర వైద్యుని నిర్ధారణ పరీక్ష అవసరం.",
    ml: "എല്ലാ പ്രവചനങ്ങൾക്കും അംഗീകൃത നേത്രരോഗവിദഗ്ദ്ധന്റെ സ്ഥിരീകരണ പരിശോധന ആവശ്യമാണ്.",
  },
