    ta: "சாதாரண புகைப்படத்தில் தெரியாத மறைந்திருக்கும் விழித்திரை வீக்கத்தை (DME) கண்டறிகிறது",
    te: "ఫండస్‌లో కనిపించని దాగి ఉన్న సబ్-రెటీనా మాక్యులార్ ఎడెమా (DME)ను గుర్తిస్తుంది",
    ml: "സാധാരണ ഫോട്ടോകളിൽ കാണാത്ത മറഞ്ഞിരിക്കുന്ന മാക്യുലർ എഡിമ (DME) കണ്ടെത്തുന്നു",
