    te: "సమగ్ర పరీక్ష మరియు రోగనిర్ధారణ కోసం దయచేసి అర్హత కలిగిన నేత్ర నిపుణుడిని సంప్రదించండి.",
    ml: "കൃത്യമായ പരിശോധനയ്ക്കും രോഗനിർണയത്തിനുമായി ഒരു നേത്രരോഗവിദഗ്ദ്ധനെ സമീപിക്കുക.",
