    te: "కర్ణాటక, మహారాష్ట్ర మరియు ఢిల్లీ పరిసరాల్లోని సమీప స్క్రీనింగ్ కేంద్రాలను కనుగొనండి.",
    ml: "കർണാടക, മഹാരാഷ്ട്ര, ഡൽഹി എന്നിവിടങ്ങളിലെ അടുത്തുള്ള പരിശോധനാ കേന്ദ്രങ്ങൾ കണ്ടെത്തുക.",
