  "journeyStep1Desc": {
    hi: "परिणामों की गोपनीय डिलीवरी के लिए आपकी प्रोफ़ाइल और फोन नंबर सत्यापित हैं।",
    kn: "ಫಲಿತಾಂಶಗಳು ಮತ್ತು ಕ್ಲಿನಿಕ್ ಎಚ್ಚರಿಕೆಗಳ ಗೌಪ್ಯ ವಿತರಣೆಗಾಗಿ ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಮತ್ತು ಫೋನ್ ಸಂಖ್ಯೆಯನ್ನು ಪರಿಶೀಲಿಸಲಾಗಿದೆ.",
    ta: "முடிவுகளை பாதுகாப்பாக அனுப்ப உங்கள் விவரங்கள் மற்றும் தொலைபேசி எண் சரிபார்க்கப்படுகின்றன.",
    te: "ఫలితాల డెలివరీ కోసం మీ ప్రొఫైల్ మరియు ఫోన్ నంబర్ ధృవీకరించబడ్డాయి.",
    ml: "ഫലങ്ങൾ സുരക്ഷിതമായി എത്തിക്കാൻ നിങ്ങളുടെ വിവരങ്ങൾ സ്ഥിരീകരിച്ചിരിക്കുന്നു.",
  },
