  "journeyStep3Desc": {
    hi: "रेटिनागार्ड ने छवि फोकस का सत्यापन किया और आगे की जांच की आवश्यकता वाले किसी भी लक्षण की पहचान की।",
    kn: "ರೆಟಿನಾಗಾರ್ಡ್ ಚಿತ್ರದ ಫೋಕಸ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿದೆ ಮತ್ತು ಹೆಚ್ಚಿನ ಕ್ಲಿನಿಕಲ್ ವಿಮರ್ಶೆಯ ಅಗತ್ಯವಿರುವ ಯಾವುದೇ ಲಕ್ಷಣಗಳನ್ನು ಗುರುತಿಸಲು ತಂಡಕ್ಕೆ ಸಹಾಯ ಮಾಡಿದೆ.",
    ta: "ரெட்டினாகார்ட் படத் தெளிவை சரிபார்த்து கூடுதல் பரிசோதனை தேவைப்படும் அறிகுறிகளை அடையாளம் கண்டுள்ளது.",
    te: "రెటీనాగార్డ్ ఇమేజ్ ఫోకస్‌ను ధృవీకరించింది మరియు తదుపరి సమీక్ష అవసరమయ్యే సంకేతాలను గుర్తించింది.",
    ml: "ചിത്രത്തിന്റെ ഗുണനിലവാരം ഉറപ്പുവരുത്തുകയും കൂടുതൽ പരിശോധന ആവശ്യമുള്ള ലക്ഷണങ്ങൾ കണ്ടെത്തുകയും ചെയ്തു.",
  },
