const origTextMap = new WeakMap<Node, string>();
const origPlaceholderMap = new WeakMap<HTMLInputElement | HTMLTextAreaElement, string>();
const origAriaMap = new WeakMap<HTMLElement, string>();
const origTitleMap = new WeakMap<HTMLElement, string>();

// Reverse lookup index: maps lowercased English phrase to TRANSLATIONS key
const enPhrasesToKey = new Map<string, string>();
if (TRANSLATIONS && TRANSLATIONS.en) {
  for (const [key, val] of Object.entries(TRANSLATIONS.en)) {
    if (typeof val === 'string' && val.trim()) {
      enPhrasesToKey.set(val.trim().toLowerCase(), key);
    }
  }
}

/**
 * Searches the lexicon and translations for a match (exact, trimmed, punctuation/symbol-stripped).
 */
export function lookupTranslation(text: string, targetLang: LanguageCode): string | null {
  if (targetLang === 'en' || !text) return null;
  const trimmed = text.trim();
  if (!trimmed) return null;

  const nonEn = targetLang as Exclude<LanguageCode, 'en'>;

  // 1. Direct match in MULTILINGUAL_LEXICON
  if (MULTILINGUAL_LEXICON[trimmed] && MULTILINGUAL_LEXICON[trimmed][nonEn]) {
    return MULTILINGUAL_LEXICON[trimmed][nonEn];
  }

  // 2. Case-insensitive match in MULTILINGUAL_LEXICON
  const lower = trimmed.toLowerCase();
  for (const [key, translations] of Object.entries(MULTILINGUAL_LEXICON)) {
    if (key.toLowerCase() === lower && translations[nonEn]) {
      return translations[nonEn];
    }
  }

  // 3. Match against TRANSLATIONS via English string reverse lookup
  const transKey = enPhrasesToKey.get(lower);
  if (transKey && TRANSLATIONS[nonEn] && TRANSLATIONS[nonEn][transKey]) {
    return TRANSLATIONS[nonEn][transKey];
  }

  // 4. Match against TRANSLATIONS by key directly
  if (TRANSLATIONS[nonEn] && TRANSLATIONS[nonEn][trimmed]) {
    return TRANSLATIONS[nonEn][trimmed];
  }

  // 5. Check trailing punctuation (., :, ?, !, ,, ;)
  const trailingPunctMatch = trimmed.match(/^(.+?)([:.?!,;]+)$/);
  if (trailingPunctMatch) {
    const core = trailingPunctMatch[1];
    const punct = trailingPunctMatch[2];
    const transCore = lookupTranslation(core, targetLang);
    if (transCore) {
      return `${transCore}${punct}`;
    }
  }

  // 6. Check leading bullet / status symbols (•, ✓, ✕, →, ←, ★, *)
  const leadingSymbolMatch = trimmed.match(/^([•✓✕→←★*]\s*)(.+)$/);
  if (leadingSymbolMatch) {
    const symbol = leadingSymbolMatch[1];
    const rest = leadingSymbolMatch[2];
    const transRest = lookupTranslation(rest, targetLang);
    if (transRest) {
      return `${symbol}${transRest}`;
    }
  }

  // 7. Check leading numbering (e.g. "1. ", "01. ", "1 - ")
  const leadingNumMatch = trimmed.match(/^(\d+[\.\-]\s*)(.+)$/);
  if (leadingNumMatch) {
    const numPrefix = leadingNumMatch[1];
    const rest = leadingNumMatch[2];
    const transRest = lookupTranslation(rest, targetLang);
    if (transRest) {
      return `${numPrefix}${transRest}`;
    }
  }

  // 8. Check wrapped in parentheses (e.g. "(Optional)", "(Sign in)")
  const parenMatch = trimmed.match(/^\((.+)\)$/);
  if (parenMatch) {
    const inner = parenMatch[1];
    const transInner = lookupTranslation(inner, targetLang);
    if (transInner) {
      return `(${transInner})`;
    }
  }

  return null;
}

/**
 * Live DOM Translation Engine
 * Sweeps the DOM tree and replaces English phrases with the active language,
 * and seamlessly restores pristine English when 'en' is selected.
 */
export function applyDomTranslations(root: HTMLElement | null, language: LanguageCode) {
  if (!root || typeof window === 'undefined') return;

  const nonEn = language !== 'en' ? (language as Exclude<LanguageCode, 'en'>) : null;

  // 1. Process Text Nodes using a TreeWalker
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: (node) => {
      const parent = node.parentElement;
      if (!parent) return NodeFilter.FILTER_REJECT;
      const tag = parent.tagName.toLowerCase();
      if (['script', 'style', 'svg', 'code', 'pre', 'noscript'].includes(tag)) {
        return NodeFilter.FILTER_REJECT;
      }
      if (parent.closest('[data-no-translate]')) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });

  const nodesToProcess: Text[] = [];
  while (walker.nextNode()) {
    nodesToProcess.push(walker.currentNode as Text);
  }

  for (const textNode of nodesToProcess) {
    const currentVal = textNode.nodeValue || '';
    const trimmed = currentVal.trim();
    if (!trimmed) continue;

    // Cache original text on first visit
    if (!origTextMap.has(textNode)) {
      origTextMap.set(textNode, currentVal);
    }

    const orig = origTextMap.get(textNode) || currentVal;
    const origTrimmed = orig.trim();

    if (!nonEn) {
      // Revert to pristine English
      if (textNode.nodeValue !== orig) {
        textNode.nodeValue = orig;
      }
    } else {
      // Translate to target language
      const translated = lookupTranslation(origTrimmed, nonEn);
      if (translated) {
        // Preserve surrounding whitespace
        const prefix = orig.match(/^\s*/)?.[0] || '';
        const suffix = orig.match(/\s*$/)?.[0] || '';
        const finalVal = `${prefix}${translated}${suffix}`;
        if (textNode.nodeValue !== finalVal) {
          textNode.nodeValue = finalVal;
        }
      }
    }
  }

  // 2. Process Input and Textarea Placeholders
  const inputs = root.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>('input[placeholder], textarea[placeholder]');
  inputs.forEach((input) => {
    if (!origPlaceholderMap.has(input)) {
      origPlaceholderMap.set(input, input.placeholder);
    }
    const origPlaceholder = origPlaceholderMap.get(input) || input.placeholder;
    if (!nonEn) {
      if (input.placeholder !== origPlaceholder) {
        input.placeholder = origPlaceholder;
      }
    } else {
      const translated = lookupTranslation(origPlaceholder, nonEn);
      if (translated && input.placeholder !== translated) {
        input.placeholder = translated;
      }
    }
  });

  // 3. Process aria-label and title attributes for complete accessibility localization
  const elementsWithLabels = root.querySelectorAll<HTMLElement>('[aria-label], [title]');
  elementsWithLabels.forEach((el) => {
    if (el.hasAttribute('aria-label')) {
      const origAria = origAriaMap.get(el) ?? el.getAttribute('aria-label')!;
      origAriaMap.set(el, origAria);
      if (!nonEn) {
        if (el.getAttribute('aria-label') !== origAria) {
          el.setAttribute('aria-label', origAria);
        }
      } else {
        const translated = lookupTranslation(origAria, nonEn);
        if (translated && el.getAttribute('aria-label') !== translated) {
          el.setAttribute('aria-label', translated);
        }
      }
    }
    if (el.hasAttribute('title')) {
      const origTitle = origTitleMap.get(el) ?? el.getAttribute('title')!;
      origTitleMap.set(el, origTitle);
      if (!nonEn) {
        if (el.getAttribute('title') !== origTitle) {
          el.setAttribute('title', origTitle);
        }
      } else {
        const translated = lookupTranslation(origTitle, nonEn);
        if (translated && el.getAttribute('title') !== translated) {
          el.setAttribute('title', translated);
        }
      }
    }
  });
}
